"use client";

import { useEffect, useState } from "react";
import { apiFetch } from "../../lib/api";

export default function Dashboard() {
  const [userRole, setUserRole] = useState(null);
  const [householdData, setHouseholdData] = useState({ entries: [], totalCO2: 0 });
  const [companyData, setCompanyData] = useState([]);
  const [matches, setMatches] = useState([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);

  const token = typeof window !== "undefined" ? localStorage.getItem("token") : null;

  useEffect(() => {
    if (!token) {
      setLoading(false);
      return;
    }

    try {
      const payload = JSON.parse(atob(token.split(".")[1]));
      setUserRole(payload.role);

      if (payload.role === "household") {
        fetchHouseholdData();
      } else if (payload.role === "company") {
        fetchCompanyData();
      } else {
        setLoading(false); // collectors/admins currently have no dashboard
      }
    } catch (err) {
      setError("Invalid token");
      setLoading(false);
    }
  }, [token]);

  const fetchHouseholdData = async () => {
    try {
      const entries = await apiFetch("/api/waste/my", "GET", null, token);

      // Calculate total CO2 saved
      const CO2_FACTORS = { plastic: 1.5, metal: 2.0, organic: 0.5, paper: 1.0 };
      const totalCO2 = entries.reduce(
        (sum, e) => sum + (CO2_FACTORS[e.type] || 0) * (e.quantityKg || 0),
        0
      );

      setHouseholdData({ entries: entries || [], totalCO2 });
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const fetchCompanyData = async () => {
    try {
      const listings = await apiFetch("/api/company/waste", "GET", null, token);
      setCompanyData(listings || []);

      const matchData = await apiFetch("/api/company/matches", "GET", null, token);
      setMatches(matchData || []);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  if (!token) return <p>Please login to view your dashboard</p>;
  if (loading) return <p>Loading...</p>;
  if (error) return <p style={{ color: "red" }}>Error: {error}</p>;

  return (
    <div style={{ padding: "20px", fontFamily: "Arial, sans-serif" }}>
      <h1>Dashboard</h1>

      {/* Household Dashboard */}
      {userRole === "household" && (
        <div>
          <h2>Household Waste Summary</h2>
          <p>Total Entries: {householdData.entries.length}</p>
          <p>Total CO₂ Saved: {householdData.totalCO2.toFixed(2)} kg</p>

          {householdData.entries.length > 0 ? (
            <table border="1" cellPadding="5">
              <thead>
                <tr>
                  <th>Type</th>
                  <th>Quantity (kg)</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {householdData.entries.map((e) => (
                  <tr key={e._id}>
                    <td>{e.type}</td>
                    <td>{e.quantityKg || 0}</td>
                    <td>{e.status || "Pending"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <p>No waste entries yet</p>
          )}
        </div>
      )}

      {/* Company Dashboard */}
      {userRole === "company" && (
        <div>
          <h2>Company Listings</h2>
          {companyData.length > 0 ? (
            <table border="1" cellPadding="5">
              <thead>
                <tr>
                  <th>Material</th>
                  <th>Quantity (kg)</th>
                  <th>Frequency</th>
                  <th>Available</th>
                </tr>
              </thead>
              <tbody>
                {companyData.map((c) => (
                  <tr key={c._id}>
                    <td>{c.materialType}</td>
                    <td>{c.quantityKg || 0}</td>
                    <td>{c.frequency || "-"}</td>
                    <td>{c.available ? "Yes" : "No"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <p>No company listings yet</p>
          )}

          <h3>Potential Matches</h3>
          {matches.length > 0 ? (
            matches.map((m, idx) => (
              <div key={idx} style={{ marginBottom: "15px" }}>
                <p>
                  Listing: {m.listing.materialType} ({m.listing.quantityKg || 0}kg)
                </p>
                {m.matches.length > 0 ? (
                  <ul>
                    {m.matches.map((match) => (
                      <li key={match._id}>
                        {match.materialType} ({match.quantityKg || 0}kg) by Company{" "}
                        {match.companyId}
                      </li>
                    ))}
                  </ul>
                ) : (
                  <p>No matches yet</p>
                )}
              </div>
            ))
          ) : (
            <p>No matches found</p>
          )}
        </div>
      )}

      {/* Collector/Admin Dashboard placeholder */}
      {userRole === "collector" && <p>Collector dashboard coming soon.</p>}
    </div>
  );
}
